∀ {c : Type u_1} [inst : Fintype c] [DecidableEq c] (B G : Matrix c c ℚ),
  B * G * B = B →
    ∀ (t : c → ℝ) (d : c → ℤ),
      ((B.map ⇑(Rat.castHom ℝ)).mulVec t = fun j => ↑(d j)) →
        have Br := B.map ⇑(Rat.castHom ℝ);
        have Gr := G.map ⇑(Rat.castHom ℝ);
        have a := G.num.mulVec d;
        (Br.mulVec fun j => ↑(a j) / ↑G.den) = Br.mulVec (Gr.mulVec fun j => ↑(d j)) ∧
          Br.mulVec (Gr.mulVec fun j => ↑(d j)) = (Br * Gr * Br).mulVec t ∧ (Br * Gr * Br).mulVec t = Br.mulVec t

