∀ {n : ℕ} (R C : Matrix (Fin n) (Fin n) ℂ) (μ : ℂ),
  R.transpose = R →
    C.transpose = C →
      have h := Matrix.fromBlocks R C (C.map Star.star) ((2 * μ) • 1 - R);
      have J := Matrix.fromBlocks 0 1 (-1) 0;
      h * J + J * h.transpose = (2 * μ) • J

